{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is negative or shows early negative momentum.",
    "Increase forecast slightly after a sharp spike in price if sentiment remains neutral or positive.",
    "Apply mean reversion bias if forecast is significantly above recent 7-day average and sentiment is weak.",
    "Reduce forecast overshoot after spikes by 10-15% if sentiment is neutral or slightly negative.",
    "Increase forecast sensitivity to sentiment shifts in the last 5 days — especially if sentiment turns positive after a dip.",
    "Avoid overreacting to short-term volatility; use 30-day moving average as a smoothing anchor for long-term forecasts."
  ]
}
